// Neshimot — daily reminder as a calendar file (Vercel serverless function).
// GET /api/reminder?id=box&lang=he&d=20261124&t=0730
// Returns a repeating daily event (.ics) at the visitor's local time, starting on date d.
// The text comes from api/_reminder-data.json, generated by build.mjs, so nothing the visitor
// sends ends up in the file except a known practice id, a date and a time.

const DATA = require('./_reminder-data.json');

const esc = (s) => String(s).replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\r?\n/g, '\\n');

// RFC 5545: content lines are at most 75 octets; longer lines continue on the next line after a space
function fold(line) {
  const out = [];
  let cur = '';
  let bytes = 0;
  for (const ch of line) {
    const b = Buffer.byteLength(ch);
    if (bytes + b > 75) {
      out.push(cur);
      cur = ` ${ch}`;
      bytes = 1 + b;
    } else {
      cur += ch;
      bytes += b;
    }
  }
  out.push(cur);
  return out.join('\r\n');
}

function validDate(d) {
  if (!/^\d{8}$/.test(d)) return false;
  const y = +d.slice(0, 4), m = +d.slice(4, 6), day = +d.slice(6, 8);
  const dt = new Date(Date.UTC(y, m - 1, day));
  return y >= 2024 && y <= 2100 && dt.getUTCMonth() === m - 1 && dt.getUTCDate() === day;
}

module.exports = function handler(req, res) {
  const q = new URL(req.url, 'http://localhost').searchParams;
  const lang = q.get('lang') === 'he' ? 'he' : 'en';
  const d = q.get('d') || '';
  const tm = q.get('t') || '';
  if (!validDate(d) || !/^([01]\d|2[0-3])[0-5]\d$/.test(tm)) {
    res.statusCode = 400;
    res.setHeader('Content-Type', 'text/plain; charset=utf-8');
    return res.end('Bad reminder request');
  }
  const text = DATA[lang];
  const id = q.get('id');
  const known = id && Object.prototype.hasOwnProperty.call(text, id) && typeof text[id] === 'object';
  const ev = known ? text[id] : text.any;

  const now = new Date().toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');
  const lines = [
    'BEGIN:VCALENDAR',
    'VERSION:2.0',
    'PRODID:-//Neshimot//Daily breath//EN',
    'CALSCALE:GREGORIAN',
    'METHOD:PUBLISH',
    'BEGIN:VEVENT',
    `UID:neshimot-${d}T${tm}-${Date.now().toString(36)}@neshimot.live`,
    `DTSTAMP:${now}`,
    // floating local time: the event happens at this clock time wherever the visitor's calendar is
    `DTSTART:${d}T${tm}00`,
    `DURATION:PT${ev.min}M`,
    'RRULE:FREQ=DAILY',
    `SUMMARY:${esc(ev.title)}`,
    `DESCRIPTION:${esc(ev.desc)}`,
    `URL:${ev.url}`,
    'BEGIN:VALARM',
    'ACTION:DISPLAY',
    `DESCRIPTION:${esc(text.alarm)}`,
    'TRIGGER:PT0M',
    'END:VALARM',
    'END:VEVENT',
    'END:VCALENDAR',
  ];
  res.statusCode = 200;
  res.setHeader('Content-Type', 'text/calendar; charset=utf-8');
  res.setHeader('Content-Disposition', 'inline; filename="neshimot-daily-reminder.ics"');
  res.setHeader('Cache-Control', 'no-store');
  res.end(`${lines.map(fold).join('\r\n')}\r\n`);
};
